// Each record is added after inspecting that batch's upstream README capture.
// These are editorial summaries, not execution/compatibility certifications.
export const reviews={
1:{fact:'README mô tả tiện ích Python chuyển nhiều loại tệp sang Markdown, ưu tiên cấu trúc cho xử lý văn bản hơn là tái tạo bản trình bày. Các định dạng có phụ thuộc tùy chọn khác nhau.',requirements:'README yêu cầu Python 3.10–3.14 và khuyến nghị môi trường ảo; định dạng cần chuyển quyết định phụ thuộc bổ sung.',steps:['Đọc Prerequisites và Optional Dependencies, chỉ chọn định dạng bạn cần.','Giữ bản gốc, chuẩn bị một file Word hoặc PDF mẫu rồi xem Usage theo đúng môi trường máy.','Đối chiếu tiêu đề, bảng và liên kết trong đầu ra; ghi phần cần sửa tay trước khi dùng với AI.'],caution:'Công cụ có thể truy cập tài nguyên bằng quyền của tiến trình đang chạy; tránh nhận file/URL không tin cậy và không cấp quyền rộng chỉ để chuyển đổi.'},
2:{fact:'Pandoc gồm thư viện chuyển đổi định dạng đánh dấu và công cụ dòng lệnh. README phân biệt định dạng đọc vào và ghi ra; không nên suy một đường chuyển đổi giữ được mọi tính năng của tài liệu.',requirements:'Chọn cách cài theo hệ điều hành từ INSTALL.md; yêu cầu phụ trợ tùy đầu ra, cần xem User’s Guide.',steps:['Trong README, tìm đúng định dạng nguồn và định dạng đích cần dùng.','Mở mục Installing và Documentation thay vì tự ghép lệnh từ bài viết hệ điều hành khác.','Dùng một đoạn văn có tiêu đề, danh sách và bảng nhỏ; đối chiếu bản xuất trước khi xử lý tài liệu dài.'],caution:'Không dùng một phép chuyển đổi thành công để kết luận tài liệu tham khảo, công thức và bố cục cũng đúng.'},
3:{fact:'README hiện giới thiệu nền tảng xử lý PDF với lựa chọn ứng dụng desktop, giao diện trình duyệt và tự triển khai máy chủ. Phần License gọi mô hình là open-core, vì vậy tính năng và điều kiện cần đọc theo bản cụ thể.',requirements:'Chọn desktop hoặc đường triển khai được tài liệu chính thức hỗ trợ; bản server có yêu cầu môi trường riêng.',steps:['Xác định bạn cần xử lý file trên máy hay dùng máy chủ; đừng chọn server chỉ vì thấy lệnh nhanh.','Tìm trong Key Capabilities đúng thao tác cần làm, chẳng hạn tách hoặc ghép PDF.','Dùng file giả, mở lại bản kết quả và kiểm tra số trang, thứ tự, phần văn bản trước khi giữ.'],caution:'Chức năng sửa/xóa nội dung PDF cần được kiểm tra trong file đầu ra; hình chữ nhật che chữ không tự chứng minh đã xóa dữ liệu.'},
4:{fact:'OCRmyPDF bổ sung lớp chữ cho PDF scan để có thể tìm kiếm hoặc sao chép. README nêu phụ thuộc ngoài Python và phân biệt bản thân phần mềm với các thành phần/giấy phép đi kèm.',requirements:'Ngoài Python phù hợp, README yêu cầu Ghostscript và Tesseract OCR; chọn hướng cài đúng hệ điều hành.',steps:['Xác định PDF là ảnh scan hay đã có lớp chữ; chỉ chọn OCR khi đúng nhu cầu.','Đọc Installation, Languages và Requirements, kiểm tra gói ngôn ngữ cần nhận dạng.','Thử một trang mẫu rồi tìm kiếm, sao chép và đối chiếu số/tiếng Việt với ảnh gốc.'],caution:'Chữ nhìn giống đúng chưa đủ; đặc biệt kiểm tra dấu, cột bảng và các chữ số quan trọng.'},
5:{fact:'Tesseract cung cấp engine OCR và chương trình dòng lệnh; dữ liệu ngôn ngữ là phần cần chọn cùng cách chạy. Tài liệu cài sẵn và tự biên dịch là hai đường khác nhau, người mới nên đọc hướng phù hợp trước.',requirements:'Cần bản cài Tesseract phù hợp và traineddata cho ngôn ngữ sử dụng; tự build còn có yêu cầu trình biên dịch.',steps:['Đọc Installing Tesseract để phân biệt bản dựng sẵn với biên dịch từ nguồn.','Chuẩn bị ảnh văn bản rõ, đúng chiều và xác định ngôn ngữ trước khi xem Running Tesseract.','So sánh văn bản nhận dạng với một bản gõ đúng ngắn, ghi loại lỗi thay vì chỉ nhìn trang xuất.'],caution:'Đây là engine OCR, không phải giải pháp tự hiểu đúng toàn bộ cấu trúc hóa đơn hay bảng biểu.'},
6:{fact:'Tabula hướng tới lấy bảng dữ liệu từ PDF. README cảnh báo nhóm tác giả gốc hiện không có thời gian tiếp tục ứng dụng người dùng cuối và nhánh phát triển có thể khác bản phát hành; tabula-java là thành phần liên quan được nhắc riêng.',requirements:'README của ứng dụng nêu Java Runtime; cần đọc lại hướng Using Tabula và Known Issues trước chọn bản tải.',steps:['Đọc ghi chú duy trì ở đầu README trước khi quyết định dùng cho quy trình lâu dài.','Kiểm tra PDF có văn bản có thể chọn, sau đó xem hướng Using Tabula theo hệ điều hành.','Chỉ thử một bảng nhỏ, so sánh cột và dòng sau xuất; nếu nguồn là ảnh scan, dừng để chọn bước OCR phù hợp.'],caution:'Giữ để tìm hiểu nhu cầu trích bảng; chưa khuyến nghị làm lựa chọn mới mặc định vì thông báo duy trì của tác giả.',maintenanceNote:'README nêu ứng dụng người dùng cuối ít khả năng nhận cập nhật từ nhóm gốc; chưa kết luận toàn bộ hệ sinh thái Tabula ngừng hoạt động.'},
7:{fact:'prompts.chat là collection prompt cộng đồng, có cách duyệt trên website và các tệp dữ liệu trong repo. Nó cung cấp đầu vào tham khảo; chất lượng kết quả vẫn phụ thuộc yêu cầu, model và dữ liệu bạn đưa vào.',requirements:'Cần một công cụ trò chuyện phù hợp nếu muốn chạy prompt; quyền sử dụng và hạn mức của công cụ đó là điều riêng.',steps:['Đọc What is this để chọn cách duyệt prompt trên web hoặc trong tệp repo.','Chọn một prompt sát công việc, viết lại đối tượng đọc, dữ liệu đầu vào và tiêu chí đạt bằng tiếng Việt.','Dùng ví dụ hư cấu, kiểm tra từng dữ kiện trong phản hồi; lưu prompt đã sửa cùng nhận xét để lần sau cải thiện.'],caution:'Không sao chép yêu cầu cấp quyền, upload dữ liệu hoặc lời hứa kết quả chỉ vì chúng xuất hiện trong prompt của cộng đồng.'},
8:{fact:'drawDB là trình biên tập sơ đồ quan hệ dữ liệu trong trình duyệt, có các chức năng làm việc với SQL được README mô tả. Chế độ phát triển local và chia sẻ có cấu hình riêng; tạo sơ đồ không đồng nghĩa đã tạo database thật.',requirements:'Dùng giao diện có sẵn hoặc xem Local Development nếu muốn tự chạy; README mô tả server/cấu hình riêng cho chia sẻ.',steps:['Bắt đầu bằng ba đối tượng quen thuộc: lớp học, học viên và đăng ký.','Phác tên cột và mối liên hệ trên sơ đồ, ghi bằng lời quan hệ một-nhiều bạn muốn diễn đạt.','Nếu xem SQL xuất ra, đọc lại tên bảng/cột trước; chưa thực thi trên database đang dùng.'],caution:'Sơ đồ là cách trao đổi thiết kế; còn cần kiểm tra khóa, ràng buộc và quyền truy cập khi xây ứng dụng thật.'},
9:{fact:'Hoppscotch hỗ trợ tạo yêu cầu và xem phản hồi API. README nêu nhiều phương thức HTTP; với người mới, cần hiểu phương thức nào chỉ đọc và phương thức nào có thể thay đổi dữ liệu trước khi thử.',requirements:'Chọn ứng dụng hoặc hướng self-host từ tài liệu; API đích có thể có yêu cầu xác thực/quyền riêng.',steps:['Mở Documentation từ README và tìm phần gửi yêu cầu HTTP cơ bản.','Dùng endpoint công khai được phép với GET, ghi URL, mã trạng thái và các trường phản hồi.','Chưa thêm token hoặc đổi sang POST/DELETE cho đến khi hiểu tác động và quyền của API đích.'],caution:'Mã phản hồi thành công không chứng minh dữ liệu đúng; không lưu credential thật trong ví dụ hoặc ảnh chụp bài học.'},
10:{fact:'CyberChef là ứng dụng biến đổi dữ liệu trong trình duyệt, ghép các thao tác thành recipe. README phân biệt công cụ web, chạy local và tích hợp kỹ thuật; các thao tác encoding, băm và mã hóa giải quyết những việc khác nhau.',requirements:'Chọn ứng dụng web chính thức hoặc hướng chạy local từ README; tự build là đường cho người có nền kỹ thuật.',steps:['Dùng chuỗi tiếng Việt hư cấu và chọn một thao tác biến đổi dễ đối chiếu.','Đọc input, recipe và output riêng, ghi lại điều mỗi bước thay đổi.','Thử phép đảo ngược khi thao tác hỗ trợ; phân biệt việc đổi cách biểu diễn với bảo vệ bí mật.'],caution:'Không dùng Base64 như một cơ chế giữ bí mật và không đưa dữ liệu riêng vào công cụ khi chưa xác định nơi xử lý.'},
11:{fact:'Joplin tổ chức ghi chú theo notebook, dùng nội dung Markdown và có các đường nhập/xuất dữ liệu. README mô tả cách làm offline-first cùng nhiều lựa chọn đồng bộ; lựa chọn dịch vụ và cách cấu hình vẫn cần người dùng quyết định.',requirements:'Chọn ứng dụng cho thiết bị từ phần tài liệu/tải chính thức; đồng bộ qua dịch vụ cần tài khoản và cấu hình tương ứng.',steps:['Tạo một notebook thử, đặt ba ghi chú về mục tiêu học và liên kết repo.','Thử tìm kiếm và gắn nhãn, sau đó đọc tài liệu nhập/xuất trước khi mang ghi chú cũ sang.','Nếu cần nhiều thiết bị, xem từng cách sync và mã hóa; thử với ghi chú giả rồi kiểm tra bản xuất.'],caution:'Đồng bộ thành công không thay thế việc có bản xuất hoặc sao lưu có thể đọc lại; kiểm tra dữ liệu đính kèm riêng.'},
12:{fact:'Logseq dùng các khối và liên kết để tổ chức tri thức. README hiện có nhánh Database Version với cảnh báo beta, còn ứng dụng mobile/RTC được nêu ở mức alpha; điều này ảnh hưởng cách chọn phiên bản và giữ dữ liệu.',requirements:'Đọc Database Version và How can I use it để chọn đúng nhánh sản phẩm; không nhập ngay kho ghi chú duy nhất vào bản thử.',steps:['Đọc cảnh báo phiên bản ở đầu README, phân biệt đường dùng hiện tại với tính năng thử nghiệm.','Dùng vài ghi chú hư cấu để hiểu block, liên kết và cách tra lại một ý.','Kiểm tra cách sao lưu/khôi phục cho nhánh đã chọn trước khi đồng bộ hoặc nhập dữ liệu thật.'],caution:'README cảnh báo khả năng mất dữ liệu ở các phần đang thử; cần bản sao độc lập, không chỉ dựa vào sync.'},
13:{fact:'AppFlowy có đường cài cho người dùng cuối và đường phát triển từ mã nguồn. README dẫn riêng tới ứng dụng desktop/mobile và hướng self-host; người chỉ muốn dùng ghi chú không cần mặc định biên dịch dự án.',requirements:'Chọn User Installation đúng thiết bị; tự phát triển hoặc self-host cần đọc tài liệu riêng về môi trường.',steps:['Mở User Installation và chọn bản dành cho hệ điều hành của bạn.','Phác một bảng theo dõi repo với tên, nguồn, điều muốn thử và trạng thái.','Đọc điều kiện lưu/đồng bộ và các chức năng AI trước khi thêm tài liệu hoặc tài khoản thật.'],caution:'Không gộp điều kiện của ứng dụng, dịch vụ cloud và tính năng AI thành một lời hứa miễn phí hoặc riêng tư.'},
14:{fact:'AFFiNE kết hợp tài liệu và canvas trong một workspace; README còn giới thiệu AI và các đường dùng/tự triển khai. Giá trị để người mới khảo sát là chuyển giữa cách viết tuyến tính và cách sắp ý tưởng bằng hình.',requirements:'Phân biệt bản dùng sẵn với Self-Host/Building; tính năng AI và dịch vụ kèm theo cần đối chiếu điều kiện riêng.',steps:['Chọn một brief hư cấu, chia phần mục tiêu và ý tưởng thành các khối nhỏ.','Đọc Features để biết nội dung nào có thể trình bày trong tài liệu hoặc trên canvas.','Trước khi dùng cho nhóm, kiểm tra cách lưu, xuất và chia sẻ thay vì chỉ nhìn ảnh demo.'],caution:'Không coi một workspace hỗ trợ AI là đã có sẵn quyền dùng mọi model hay hạn mức không giới hạn.'},
15:{fact:'SiYuan tập trung quản lý tri thức cá nhân theo khối và tham chiếu chi tiết. README có mục FAQ về lưu dữ liệu, đồng bộ, nâng cấp và chi phí; đó là các câu cần đọc trước khi chọn cho kho ghi chú lâu dài.',requirements:'Chọn đường tải trong Download Setup theo thiết bị; xem FAQ về lưu dữ liệu và cách đồng bộ được hỗ trợ.',steps:['Viết một ghi chú mẫu rồi chia thành vài khối có thể tham chiếu.','Đọc phần dữ liệu được lưu thế nào và hạn chế của cách sync bạn định dùng.','Thử xuất/giữ bản sao ghi chú mẫu rồi mới cân nhắc nhập tài liệu làm việc.'],caution:'Không dùng một dịch vụ đồng bộ thư mục bất kỳ khi tài liệu không khuyến nghị; thay đổi đồng thời có thể ảnh hưởng dữ liệu.'},
16:{fact:'Trilium Notes tổ chức ghi chú theo cây, hướng tới kho kiến thức cá nhân lớn. README phân biệt stable release với nightly không ổn định, có hướng desktop, trình duyệt và server; chọn đúng cách dùng giúp giảm bước không cần thiết.',requirements:'Chọn bản stable và hướng Installation phù hợp; bản server cần môi trường vận hành riêng.',steps:['Đọc Download để tránh chọn nightly chỉ vì ngày cập nhật mới hơn.','Tạo cây ghi chú cho một dự án hư cấu gồm yêu cầu, quyết định và tài nguyên.','Mở tài liệu có sẵn trong ứng dụng hoặc User Guide, tìm cách lưu và phục hồi trước nhập dữ liệu cũ.'],caution:'Phân biệt TriliumNext với các phiên bản/kho cũ khi làm theo hướng dẫn chuyển dữ liệu.'},
17:{fact:'Outline là mã nguồn của một hệ thống knowledge base cộng tác. README nói người chỉ muốn dùng có thể chọn dịch vụ hosted; tự chạy và phát triển là hai nhu cầu khác, với tài liệu cài đặt/vận hành riêng.',requirements:'Nếu tự triển khai, đọc hosting documentation được dẫn từ Installation; dùng dịch vụ hosted có điều kiện tài khoản riêng.',steps:['Xác định bạn muốn viết wiki hay muốn vận hành một server wiki.','Phác một trang tài liệu mẫu với mục đích, người phụ trách và ngày rà lại.','Đọc tài liệu về tài khoản và quyền chia sẻ trước khi mời người khác hoặc đưa nội dung nhóm lên.'],caution:'Không tự mở công khai knowledge base nội bộ; khả năng cộng tác không thay thế phân quyền.'},
18:{fact:'Docmost cung cấp wiki cộng tác với spaces, lịch sử trang và quản lý quyền. README phân biệt lõi AGPL với phần enterprise ở các thư mục riêng; vì vậy không nên gộp điều kiện giấy phép của mọi phần vào một nhãn.',requirements:'Xem Getting started để chọn tài liệu self-host hoặc dịch vụ cloud; kiểm tra quyền người dùng và gói chức năng cần dùng.',steps:['Thiết kế một space mẫu cho dự án hư cấu và ba trang có đường đọc rõ.','Đọc cách tổ chức nhóm/quyền trước khi chia sẻ một trang ra ngoài.','Thử quy trình sửa rồi xem lịch sử bằng dữ liệu giả; kiểm tra lại điều kiện tính năng định dùng.'],caution:'Tên gọi open-source của dự án không có nghĩa toàn bộ phần enterprise được dùng dưới cùng một điều kiện.'},
19:{fact:'Standard Notes là ứng dụng ghi chú với cơ chế đồng bộ mã hóa đầu cuối được README mô tả. Có đường dùng ứng dụng web, tải trên thiết bị và tự host; tài khoản, khóa khôi phục và cách xuất dữ liệu cần được hiểu cùng tính năng ghi chú.',requirements:'Chọn ứng dụng và cách dùng theo tài liệu; đọc việc quản lý tài khoản, đồng bộ và tùy chọn self-host trước thử dữ liệu quan trọng.',steps:['Bắt đầu bằng ghi chú hư cấu và xác định nơi bản dữ liệu được lưu.','Đọc tài liệu về truy cập tài khoản và khôi phục, không chỉ bước đăng ký.','Kiểm tra bản xuất có đọc lại được và xem điều kiện tính năng cần dùng trên các thiết bị.'],caution:'Không suy cơ chế mã hóa là bảo đảm phục hồi khi quên thông tin đăng nhập hoặc mất dữ liệu.'},
20:{fact:'Anytype Desktop giới thiệu cách tổ chức tri thức theo đối tượng và khối, với cách làm local-first. README dẫn bản cài cho người dùng và đường build cho lập trình viên; giấy phép được nêu là source available, không nên tự đổi thành nhãn mã nguồn mở chung.',requirements:'Chọn Quick Start hoặc bản cài từ Releases; tự build có nhiều phụ thuộc và không cần cho người chỉ muốn thử ghi chú.',steps:['Lập ba loại thông tin mẫu như sách, tác giả và ghi chú, rồi xác định mối liên hệ.','Đọc Quick Start thay vì bắt đầu từ chuỗi lệnh xây dựng mã nguồn.','Xem License, lưu trữ và sync trước khi đưa kho tri thức riêng vào hoặc chia sẻ với nhóm.'],caution:'Cần kiểm tra điều kiện Any Source Available License theo cách dùng dự kiến; public code không đồng nghĩa mọi quyền tái phân phối.'},
21:{fact:'n8n kết hợp canvas workflow với các bước xử lý và tích hợp dịch vụ. README nêu lựa chọn self-host/cloud và giấy phép fair-code; bài khởi đầu nên tập trung cách dữ liệu đi qua các bước trước khi nối tài khoản thật.',requirements:'Đường tự triển khai trong Quick Start dùng Docker; dùng cloud cần xem điều kiện dịch vụ và tài khoản riêng.',steps:['Viết rõ dữ liệu vào và kết quả ra của một tác vụ nhỏ, không bắt đầu bằng workflow nhiều dịch vụ.','Đọc Quick Start và Key Capabilities, phân biệt việc chạy n8n với quyền của từng tích hợp.','Dùng ba dòng dữ liệu giả để phác bước chuẩn hóa và kiểm tra đầu ra trước thêm trigger/credential.'],caution:'Workflow có thể gửi dữ liệu hoặc kích hoạt hành động ở dịch vụ ngoài; chỉ bật sau khi biết từng bước làm gì.'},
22:{fact:'Activepieces tổ chức tự động hóa bằng các pieces có thể mở rộng. README giới thiệu giao diện dựng luồng và liên hệ với hệ sinh thái MCP; khả năng của một kết nối không đại diện cho mọi kết nối khác.',requirements:'Chọn đường Deploy hoặc dịch vụ từ tài liệu; một piece có thể cần credential và điều kiện riêng của nhà cung cấp.',steps:['Chọn một thao tác mẫu như đổi tên trường dữ liệu thay vì gửi thư hoặc cập nhật CRM.','Đọc mô tả piece liên quan để xác định đầu vào, đầu ra và quyền.','Phác luồng với dữ liệu giả, đánh dấu bước nào mới là xử lý local và bước nào gọi dịch vụ.'],caution:'Không bật tất cả pieces hoặc MCP chỉ để khám phá; thêm kết nối có thể mở rộng quyền truy cập.'},
23:{fact:'Windmill là nền tảng cho script, API, job nền, workflow và giao diện công cụ nội bộ. README mô tả việc ghép script thành flow và tạo giao diện; đây là hướng phù hợp khi đã biết một chút về mã và dữ liệu đầu vào.',requirements:'Đọc Main Concepts trước, rồi chọn How to self-host hoặc môi trường được tài liệu hỗ trợ; script cần runtime phù hợp.',steps:['Bắt đầu bằng một script biến đổi văn bản hư cấu có đầu vào/đầu ra xác định.','Đọc Main Concepts để phân biệt script, flow, job và giao diện gọi chúng.','Trước khi thêm lịch chạy hoặc secret, xác định tác dụng phụ và cách xem kết quả từng bước.'],caution:'Một giao diện tự sinh không biến script bất kỳ thành thao tác an toàn; cần hiểu mã được chạy bằng quyền nào.'},
24:{fact:'Flowise từng tập trung dựng ứng dụng/agent AI bằng giao diện trực quan. README hiện tuyên bố repo đã archived và dẫn tới thảo luận Future of Flowise; đây là thông tin phải đọc trước các phần Quick Start còn lưu lại.',requirements:'Chỉ đọc tham khảo lịch sử và cấu trúc; không coi hướng cài còn trong README là khuyến nghị hiện hành cho dự án mới.',steps:['Đọc thông báo archived ở đầu README và đường dẫn Future of Flowise.','Quan sát cách tác giả biểu diễn node/luồng để hiểu khái niệm agent trực quan.','Nếu cần giải pháp mới, lập yêu cầu rồi đánh giá dự án còn phù hợp, không cài theo một bài cũ chỉ vì nhiều sao.'],caution:'Bài giữ để giải thích và giúp tránh nhầm tình trạng; không đưa Flowise thành công cụ bắt buộc cho người mới.'},
25:{fact:'Dify gom các thành phần workflow AI, hỏi đáp trên tài liệu, agent và quản lý model trong một nền tảng. README phân biệt quick start server với phát triển từ mã nguồn; giao diện là một phần, còn tài khoản model và dữ liệu cần quyết định riêng.',requirements:'Quick Start nêu máy tối thiểu 2 CPU core, RAM 4 GiB và Docker Compose theo bản yêu cầu; chưa chứng nhận đủ cho mọi workload.',steps:['Phác trợ lý trên một đoạn nội dung giả có ba câu hỏi và đáp án đối chiếu.','Đọc Quick Start và Key features để biết cần server, model và nguồn dữ liệu nào.','Chưa nhập key hoặc upload tài liệu thật cho tới khi rõ chi phí, quyền và nơi xử lý.'],caution:'Có pipeline RAG không có nghĩa câu trả lời luôn bám đúng tài liệu; vẫn cần bộ câu hỏi và cách kiểm tra.'},
26:{fact:'Appsmith là nền tảng low-code cho công cụ nội bộ như dashboard và bảng quản trị. README cung cấp lựa chọn Appsmith Cloud và cài trên máy; cần tách việc dựng giao diện khỏi quyền truy cập nguồn dữ liệu phía sau.',requirements:'Chọn một hướng trong Installation; cloud cần tài khoản, tự host cần môi trường theo tài liệu cài.',steps:['Phác một bảng danh mục hư cấu với thao tác chỉ đọc và bộ lọc rõ ràng.','Đọc Installation và Learning Resources, chọn đúng đường dùng trước khi xem Development.','Với mỗi thao tác sửa/lưu dự kiến, ghi dữ liệu nào sẽ thay đổi và ai được phép làm.'],caution:'Không nối database production hoặc dùng tài khoản quyền cao chỉ vì giao diện thử đã hiển thị đúng.'},
27:{fact:'ToolJet hướng tới công cụ nội bộ với giao diện, truy vấn và kết nối database/API/SaaS. README hiện có đường xây app bằng coding agent/MCP và phần tính năng theo edition; không nên suy mọi phần AI có cùng điều kiện với lõi.',requirements:'Chọn cloud hoặc self-host trong Quickstart và đọc bảng Community/Enterprise theo tính năng định dùng.',steps:['Xác định một trang tra cứu dữ liệu giả trước, chưa thêm nút ghi/xóa.','Đọc Quickstart và Features để biết phần nào thuộc edition nào.','Nếu dùng agent/MCP sau này, kiểm tra hợp đồng dữ liệu và quyền trước cấp kết nối.'],caution:'Một app do prompt tạo vẫn cần đối chiếu truy vấn, quyền và môi trường, không chỉ kiểm tra vẻ ngoài.'},
28:{fact:'Budibase giới thiệu nền tảng cho app, workflow và agent xử lý công việc vận hành. README nói các tác vụ có thể tạo record, định tuyến phê duyệt và thông báo; vì thế thử bằng dữ liệu giả là bước quan trọng trước nối hệ thống doanh nghiệp.',requirements:'Chọn đường Get started cloud hoặc self-host; từng nguồn dữ liệu/model có yêu cầu tài khoản và quyền riêng.',steps:['Mô tả một yêu cầu thiết bị hư cấu, trạng thái và người phụ trách giả.','Đọc Features để phân biệt giao diện nhận yêu cầu với hành động tự động phía sau.','Liệt kê bước nào chỉ hiển thị và bước nào ghi dữ liệu/gửi thông báo trước khi chọn tích hợp.'],caution:'Không cho agent tự phê duyệt yêu cầu thật hoặc gửi thông báo chỉ để kiểm tra demo.'},
29:{fact:'NocoDB cung cấp giao diện dữ liệu dạng bảng cùng truy cập lập trình và lựa chọn triển khai. README có hướng Docker với SQLite/PostgreSQL; người mới cần biết dữ liệu được lưu ở đâu và thao tác bảng tác động đến nguồn nào.',requirements:'Đọc Installation theo backend chọn dùng; server, volume dữ liệu và cấu hình xác thực cần được giữ rõ.',steps:['Dựng mô hình danh mục bài viết hư cấu với tiêu đề, trạng thái và ngày rà soát.','Đọc Rich Spreadsheet Interface và Installation để tách giao diện khỏi backend lưu dữ liệu.','Trước nhập thật, xác định ai được xem/sửa và cách xuất hoặc khôi phục bản mẫu.'],caution:'Không sao chép credential ví dụ từ README sang cấu hình thật; không mở bảng riêng bằng link công khai tùy ý.'},
30:{fact:'Baserow kết hợp bảng dữ liệu với ứng dụng và workflow. README nêu mô hình open-core và thông báo chuyển repository từ GitLab sang GitHub; sao GitHub không nên được dùng như toàn bộ lịch sử phát triển của dự án.',requirements:'Chọn cloud hoặc một hướng Installation chính thức; đọc điều kiện premium/enterprise nếu cần chức năng ngoài lõi.',steps:['Tạo bản thiết kế bảng tài liệu mẫu với trường, kiểu dữ liệu và nhãn trạng thái.','Đọc Repository Migration Notice để dùng đúng nguồn hiện hành.','Xem Installation và Official documentation, rồi kiểm tra quyền chia sẻ và khả năng xuất trước dùng cho nhóm.'],caution:'Không lấy số sao ít hơn một dự án khác làm bằng chứng sản phẩm kém phổ biến hoặc còn mới khi đã có lịch sử ở nền tảng khác.'},
31:{fact:'Ollama hiện mô tả lựa chọn model local và cloud, có các đường cài cho macOS, Windows, Linux và Docker. Cần phân biệt phần mềm phục vụ model với bản model cụ thể và với dịch vụ chạy trên hạ tầng ngoài.',requirements:'Đọc Download đúng hệ điều hành và yêu cầu của model định chọn; dung lượng/RAM cần đối chiếu trước tải.',steps:['Ghi cấu hình máy và mục tiêu tác vụ, chưa chọn model chỉ từ tên đang được nhắc tới.','Đọc Download và Get started, phân biệt chạy model trên máy với kết nối cloud.','Trước thử, xác định file/model nào sẽ tải và cách dừng; chỉ dùng câu hỏi không có dữ liệu riêng.'],caution:'Một ứng dụng hỗ trợ local vẫn có thể được cấu hình gọi dịch vụ ngoài; phải xem chế độ thực sự đang dùng.'},
32:{fact:'Open WebUI là nền tảng giao diện AI tự triển khai, README nêu kết nối Ollama và các API tương thích. Phần giao diện, model và hệ thống người dùng là những lớp riêng; có giao diện chat không nghĩa đã có model sẵn.',requirements:'Chọn hướng How to Install, xác định backend model và cấu hình người dùng; bản Docker/Python có yêu cầu môi trường riêng.',steps:['Vẽ ba khối trình duyệt, Open WebUI và model/API để biết luồng dữ liệu.','Đọc phần cài theo backend định dùng, không trộn cấu hình local và cloud.','Kiểm tra quyền nhóm/tài khoản và nơi lưu hội thoại trước chia sẻ instance cho người khác.'],caution:'Các plugin, tools và kết nối mở rộng có thể thêm hành động; không bật hàng loạt khi mới làm quen.'},
33:{fact:'AnythingLLM có đường desktop, hosted và self-host, ghép tài liệu với model local hoặc cloud trong workspace. README còn có phần Telemetry & Privacy và outbound connections, nên cần đọc cùng tính năng chat với tài liệu.',requirements:'Chọn desktop hoặc self-host từ tài liệu, xác định model/embedding và nơi dữ liệu workspace được lưu.',steps:['Chỉ dùng bộ nội dung hư cấu có ba câu hỏi và đáp án biết trước.','Đọc Product Overview, Self-Hosting và Telemetry & Privacy trước chọn cách chạy.','Khi đánh giá, đối chiếu câu trả lời với đoạn nguồn chứ không chỉ xem ứng dụng có phản hồi.'],caution:'Không lặp lại lời hứa riêng tư tuyệt đối từ mô tả quảng bá; kết nối model và cấu hình cụ thể mới quyết định đường dữ liệu.'},
34:{fact:'RAGFlow là nền tảng RAG kết hợp khả năng agent và xử lý tài liệu. README hiện phân biệt dịch vụ cloud, local deployment và các cách tổ chức tri thức; người mới nên hiểu dữ liệu được chia/tìm lại thế nào trước khi cài hệ thống.',requirements:'Xem Local Deployment để đối chiếu tài nguyên và phụ thuộc; không mặc định máy văn phòng đủ chạy toàn bộ cấu hình.',steps:['Chọn một tài liệu mẫu có đoạn văn và bảng, ghi những câu hỏi cần trả lời.','Đọc What is RAGFlow và System Architecture để hiểu các thành phần.','Đối chiếu yêu cầu triển khai và cách quản lý dữ liệu/model rồi mới quyết định thử một hệ thống.'],caution:'Trích dẫn và truy xuất làm rõ nguồn nhưng không bảo đảm câu trả lời chính xác; cần bộ câu hỏi đối chiếu.'},
35:{fact:'Langflow cung cấp giao diện tạo flow AI, có khả năng đưa workflow ra API/MCP theo README. Repo cũng dẫn bản desktop với phụ thuộc đóng gói sẵn; dùng ứng dụng và phát triển bằng Python là các đường khác nhau.',requirements:'Chọn Langflow Desktop hoặc hướng Quickstart/Other install options đúng môi trường; model và tích hợp có điều kiện riêng.',steps:['Vẽ một flow gồm ô nhập, bước xử lý và đầu ra có tiêu chí kiểm tra.','Đọc Highlight features để biết phần nào chạy model, truy xuất hoặc gọi công cụ.','Chưa xuất flow ra API/MCP công khai trước khi rõ xác thực, quyền và nội dung đầu vào.'],caution:'Một node có thể gọi dịch vụ hoặc chạy mã; hình thức kéo-thả không làm mất yêu cầu kiểm tra tác động.'},
36:{fact:'Jan hiện có repo canonical janhq/jan, với bản cài cho nhiều hệ điều hành và kết nối model local/cloud. README tách Installation khỏi Build from Source; người chỉ muốn thử ứng dụng không cần tự xây toàn bộ mã.',requirements:'Chọn bản cài chính thức và đọc System Requirements; model local cần RAM/dung lượng, provider ngoài cần quyền tài khoản.',steps:['Dùng tên repo hiện hành để mở Installation, tránh hướng dẫn trỏ chủ sở hữu cũ mà chưa đối chiếu.','Phân biệt lựa chọn Local AI Models và Cloud Integration trong Features.','Trước chat, xác nhận model nào dùng, nơi xử lý và cách giữ hoặc xóa hội thoại mẫu.'],caution:'Các tính năng API local/MCP mở thêm khả năng tích hợp; không bật như một yêu cầu bắt buộc khi chỉ muốn đọc thử.'},
37:{fact:'GPT4All có ứng dụng desktop và gói Python, được README trình bày thành hai đường dùng riêng. Bản desktop hướng tới model trên máy; danh sách nền tảng/cấu hình cho từng bản có khác nhau và cần đọc trước tải.',requirements:'Đối chiếu Download Links và System Requirements theo CPU, hệ điều hành và kiến trúc; model có yêu cầu lưu trữ riêng.',steps:['Chọn đường ứng dụng desktop nếu mục tiêu là tìm hiểu trò chuyện trên máy, chưa cần gói Python.','Đọc giới hạn nền tảng của đúng bản tải, đặc biệt khác biệt ARM/x86.','Chọn dữ liệu câu hỏi mẫu và cách đối chiếu, không coi phản hồi trôi chảy là thông tin đã đúng.'],caution:'Không tự suy mô hình nào cũng chạy được với cùng tốc độ hoặc có cùng điều kiện giấy phép.'},
38:{fact:'Cherry Studio là ứng dụng tổ chức model, hội thoại, agent và kho tài liệu; README có mục provider để cấu hình dịch vụ/API. Việc có nhiều lựa chọn trong một ứng dụng không thay thế tài khoản hoặc quota của từng nhà cung cấp.',requirements:'Chọn Download Desktop/Getting Started đúng hệ điều hành; cấu hình provider cần thông tin và quyền phù hợp.',steps:['Ghi một tác vụ nhỏ và chọn duy nhất một đường model để hiểu trước.','Đọc phần provider và phân biệt model local với tài khoản dịch vụ bên ngoài.','Chỉ dùng ví dụ hư cấu, xem cách lưu hội thoại và dữ liệu knowledge base trước khi thêm nguồn thật.'],caution:'Không dán key vào ảnh hướng dẫn hoặc dùng app như bằng chứng mọi model được cung cấp miễn phí.'},
39:{fact:'LibreChat hiện ở repo canonical LibreChat-AI/LibreChat, có giao diện hội thoại và tính năng agent/workspace được README mô tả theo mức thử nghiệm. Những quyền đọc file, sửa file và chạy lệnh cần được xem riêng với việc chat thông thường.',requirements:'Chọn tài liệu Resources cho triển khai và provider; tính năng agent/workspace cần cấu hình quyền theo môi trường.',steps:['Đọc Features trước, chỉ chọn nhu cầu hội thoại nếu chưa cần agent có quyền làm việc với file.','Xác định provider, nơi lưu hội thoại và quyền người dùng của instance.','Khi khảo sát workspace, ghi rõ thao tác nào yêu cầu Ask/Allow/Deny; không dùng full access mặc định.'],caution:'Tính năng được đánh dấu thử nghiệm không nên dùng ngay với dữ liệu duy nhất hoặc mã production.'},
40:{fact:'LiteLLM là lớp gateway/SDK kết nối ứng dụng với nhiều nhà cung cấp model qua giao diện thống nhất. README phân biệt Python SDK với proxy server; đây là thành phần kỹ thuật cho tích hợp, không phải một model hay nguồn quota AI.',requirements:'Cần kiến thức API và provider có quyền sử dụng; chọn SDK hoặc gateway, đọc tài liệu cấu hình trước triển khai.',steps:['Vẽ đường đi ứng dụng → gateway → provider và xác định nơi đặt credential.','Đọc What is LiteLLM để chọn đúng nhu cầu tích hợp thay vì cài cả proxy cho một lần chat.','Lập tiêu chí kiểm soát truy cập, chi phí và log trước thực hiện bất kỳ yêu cầu thật nào.'],caution:'Số nhà cung cấp hỗ trợ không chứng nhận mọi endpoint/model đều có cùng tính năng hoặc giá.'},
41:{fact:'Repo Codex phân biệt coding agent CLI với trải nghiệm IDE, desktop và web. README có quickstart và cách dùng với tài khoản ChatGPT; không nên lấy lệnh của CLI rồi coi đó là hướng dẫn chung cho mọi giao diện.',requirements:'Chọn đúng Codex CLI, hệ điều hành và cách xác thực trong tài liệu chính thức; kiểm tra quyền tài khoản/hạn mức trước tác vụ.',steps:['Xác nhận bạn muốn dùng terminal hay desktop; mở đúng tài liệu cho giao diện đó.','Viết một yêu cầu chỉ đọc cấu trúc thư mục bài tập trước, chưa cho sửa nhiều file.','Khi thử sửa sau này, xem diff và checklist trên bản mẫu, giữ checkpoint để có thể quay lại.'],caution:'Codex CLI và OpenAI CLI là hai công cụ khác mục đích; không dùng hướng dẫn gọi API thay cho hướng dùng coding agent.'},
42:{fact:'Claude Code là công cụ agent làm việc với codebase qua terminal và các giao diện tích hợp. README hiện ghi đường cài npm đã deprecated và dẫn tới setup documentation, nên bài cài cũ cần được đối chiếu thay vì sao chép nguyên.',requirements:'Đọc Get started/setup đúng hệ điều hành, kiểm tra tài khoản và quyền thư mục; không mặc định npm là cách cài hiện hành.',steps:['Mở official documentation từ README, phân biệt quyền dùng sản phẩm với việc repo có thể đọc công khai.','Chọn thư mục hư cấu và yêu cầu giải thích cấu trúc trước khi cho phép thay đổi.','Đọc thao tác được đề xuất, xem thay đổi và thử khôi phục trên bản mẫu trước dùng dự án thật.'],caution:'Agent có thể gọi công cụ và thực hiện workflow Git; cần đọc quyền, dữ liệu và lưu giữ được tài liệu nêu.'},
43:{fact:'README Gemini CLI hiện có thông báo chuyển nhóm unpaid/Google One sang Antigravity CLI và lưu ý không tối ưu cho một số model mới. Do đó đây là bài giúp hiểu repo và thay đổi hiện hành, không phải mặc định khuyên người mới cài Gemini CLI.',requirements:'Đọc thông báo đầu README và tài liệu đường sản phẩm áp dụng cho loại tài khoản trước khi chọn hướng cài.',steps:['Đọc hai thông báo đầu trang trước Installation, xác định loại tài khoản của mình.','Theo liên kết cập nhật chính thức để biết sản phẩm nào đang phù hợp; không chọn theo số sao riêng.','Nếu vẫn cần tìm hiểu repo, phân biệt stable, preview và nightly; chưa gửi yêu cầu AI hay nhập key để thử tùy ý.'],caution:'Không dùng hướng dẫn cũ để hứa quota miễn phí hoặc hỗ trợ model mới; điều kiện đã thay đổi cần kiểm tra trực tiếp.'},
44:{fact:'OpenCode giới thiệu agent coding với đường terminal và desktop beta. README có các cách cài và phần Agents/Documentation; người mới cần chọn một đường dùng rõ ràng, không ghép các lệnh từ nhiều package manager.',requirements:'Đọc Installation/Documentation theo hệ điều hành và sản phẩm; model/provider và trạng thái desktop beta cần xem riêng.',steps:['Chọn CLI hoặc desktop rồi đọc đúng tài liệu, không cài cả hai chỉ để làm một việc.','Viết đề bài nhỏ có giới hạn file và điều kiện đạt trong thư mục mẫu.','Trước dùng provider, xác định đăng nhập, quota và quyền của agent; kiểm tra diff sau tác vụ.'],caution:'Một dòng cài nhanh không thay thế việc hiểu nguồn tải và quyền thực thi trên máy.'},
45:{fact:'Aider là cách pair programming với model trong terminal; README mô tả bản đồ codebase và tích hợp Git, gồm tự commit thay đổi. Các ví dụ model được nêu trong README là thông tin nguồn, không tự trở thành khuyến nghị model hiện hành cho mọi người.',requirements:'Cần môi trường terminal, hiểu Git tối thiểu và một đường model có quyền sử dụng; đọc tài liệu cài/LLM theo bản hiện tại.',steps:['Tạo repo bài tập nhỏ, lưu mốc trước khi giao tác vụ cho AI.','Đọc Git integration để biết công cụ có thể commit thay đổi như thế nào.','Chọn một sửa đổi có thể nhìn thấy và đối chiếu diff; không đưa toàn dự án thật vào chỉ để thử.'],caution:'Chi phí model và tác động Git là hai thứ cần kiểm soát riêng; commit tự động không chứng minh thay đổi đúng.'},
46:{fact:'README Continue hiện nói repository không còn được duy trì tích cực và ở chế độ read-only cho người dùng, đồng thời giới thiệu bản phát hành cuối 2.0.0. Thông báo README này cần được nói rõ dù cờ archived trong snapshot GitHub chưa bật.',requirements:'Đọc What is Continue và Final 2.0.0 Release trước khi cân nhắc bản CLI/extension; không coi repo còn truy cập là đang phát triển.',steps:['Đọc thông báo tình trạng hiện hành thay vì bắt đầu từ link cài extension.','Tìm hiểu các đường CLI, VS Code, JetBrains như thông tin tham khảo của dự án.','Với nhu cầu mới, lập tiêu chí rồi đối chiếu giải pháp còn phù hợp; chưa cài chỉ theo một bài review cũ.'],caution:'Giữ bài để giải thích tình trạng và tránh nhầm; không đề xuất làm lựa chọn mới mặc định.',maintenanceNote:'README tuyên bố không còn duy trì tích cực và read-only; metadata archived=false không phủ nhận thông báo này.'},
47:{fact:'Cline có đường CLI, desktop, IDE extension và SDK trong README hiện tại. Tính năng tạo file, chạy lệnh, duyệt web cùng cơ chế phê duyệt cần được hiểu theo giao diện cụ thể; SDK không phải bước bắt buộc cho người mới.',requirements:'Chọn một sản phẩm từ Index và tài liệu tương ứng, kiểm tra provider/model và quyền môi trường đang dùng.',steps:['Xác định bạn dùng IDE hay ứng dụng desktop, rồi mở đúng đường Docs.','Bắt đầu bằng tác vụ giải thích dự án mẫu hoặc lập kế hoạch trước khi cho chỉnh file.','Đọc từng yêu cầu quyền chạy lệnh/truy cập web; kiểm tra kết quả và giữ bản mốc.'],caution:'Khả năng headless và routine không phải lý do để bật tự động khi chưa kiểm tra tác dụng của tác vụ nhỏ.'},
48:{fact:'Roo Code mô tả các mode như Code, Architect, Ask và Debug để phân vai công việc với codebase. GitHub hiện đánh dấu repo archived; các phần giới thiệu mode vẫn giúp hiểu phương pháp nhưng không đủ để khuyên bắt đầu một hệ thống mới.',requirements:'Đọc trạng thái archived và Resources trước; nội dung giữ ở mức giới thiệu tham khảo, không hướng cài như lựa chọn đang duy trì.',steps:['Đọc cảnh báo tình trạng dự án và xác định mục tiêu là học khái niệm hay chọn công cụ mới.','So sánh nhiệm vụ hỏi/giải thích với nhiệm vụ sửa mã qua các mode được README mô tả.','Nếu cần dùng cho dự án thật, đánh giá giải pháp còn hỗ trợ và quyền tương ứng trước khi quyết định.'],caution:'Nhiều mode và nhiều sao không chứng minh tương thích hiện hành, đặc biệt với repository archived.'},
49:{fact:'OpenHands README hiện giới thiệu Agent Canvas như trung tâm điều phối coding agent qua nhiều backend. Có lựa chọn local, Docker và hạ tầng ngoài; không nên giản lược thành một chatbot tự viết mọi phần mềm.',requirements:'Đọc Quickstart và Architecture, chọn backend/môi trường chạy; từng agent/provider có điều kiện tài khoản và quyền riêng.',steps:['Vẽ sơ đồ repo mẫu, môi trường chạy và agent để biết phần nào có quyền tác động.','Đọc các lựa chọn Quickstart, phân biệt có sandbox và không sandbox.','Giới hạn đầu tiên ở tác vụ đọc hoặc giải thích; chưa bật tự động gửi báo cáo hay xử lý issue thật.'],caution:'Một control center hỗ trợ nhiều agent không tự cấp quyền thực hiện hành động thay chủ dự án.'},
50:{fact:'Goose hiện ở repo canonical aaif-goose/goose, cung cấp desktop, CLI và API cho công việc với agent. README mô tả provider và extensions qua MCP; các kết nối mở rộng cần được kiểm tra riêng với việc cài ứng dụng.',requirements:'Chọn Get started đúng thiết bị/giao diện, đọc provider phù hợp với tài khoản và quyền extension định dùng.',steps:['Dùng tên repo hiện hành rồi mở Quickstart từ phần Quick links.','Chọn một việc mẫu nhỏ và một provider; chưa thêm nhiều extension cùng lúc.','Với extension cần thiết, ghi dữ liệu nó đọc/ghi và hành động có thể làm trước cấp kết nối.'],caution:'Không suy quyền dùng nhiều provider có nghĩa mọi subscription hoặc API đều được dùng không giới hạn.'},
51:{fact:'Anthropic Skills là collection gồm thư mục chỉ dẫn, script và tài nguyên cho các nhiệm vụ cụ thể. README nói đây là cách triển khai skills cho Claude và dẫn tiêu chuẩn Agent Skills riêng; không nên đánh đồng collection này với mọi kho mang tên skill.',requirements:'Chọn đúng skill và công cụ hỗ trợ từ tài liệu; kiểm tra SKILL.md, các script/resource và license của phần định dùng.',steps:['Tìm một việc cụ thể như xử lý tài liệu rồi mở thư mục skill tương ứng, chưa cài cả collection.','Đọc đầu vào, đầu ra và công cụ mà skill yêu cầu; ghi script nào có thể chạy.','Đối chiếu đường sử dụng theo giao diện/công cụ của bạn, chỉ thử dữ liệu giả trong phạm vi được phép.'],caution:'Sao thuộc repo tổng hợp; không dùng số sao này như đánh giá riêng từng skill hoặc chứng nhận tương thích mọi agent.'},
52:{fact:'Superpowers là phương pháp làm phần mềm cho coding agent được đóng gói thành skills và chỉ dẫn. README có các đường tích hợp theo công cụ, từ xác định nhu cầu đến kiểm tra; cần chọn đúng môi trường thay vì áp dụng một lệnh chung.',requirements:'Cần coding agent được hỗ trợ và đường Installation đúng giao diện; các bước workflow còn phụ thuộc quyền dự án.',steps:['Đọc How it works để hiểu vì sao có bước hỏi rõ đề bài trước khi viết mã.','Tìm đúng công cụ trong Installation, không trộn phần Codex App với CLI hoặc agent khác.','Thử lập một kế hoạch nhỏ cùng tiêu chí xong; xem dữ liệu/việc gì workflow có thể yêu cầu thêm.'],caution:'Bộ phương pháp giúp tổ chức công việc nhưng không thay bằng chứng kiểm thử; đọc cả phần cập nhật và telemetry nếu dùng.'},
53:{fact:'Spec Kit hiện cung cấp các quy trình cho xây tính năng, sửa lỗi và đánh giá ý tưởng. README nêu đây là các lối vào độc lập, không phải ba giai đoạn bắt buộc; chọn theo việc giúp người mới tránh dựng quy trình quá lớn.',requirements:'Đọc Get started và phần tích hợp agent; chỉ dùng process/extension phù hợp với nhiệm vụ đang làm.',steps:['Xác định việc của bạn là xây mới, sửa lỗi hay đánh giá ý tưởng trước khi chọn process.','Viết một mục tiêu, giới hạn phạm vi và điều kiện nghiệm thu cho ví dụ hư cấu.','Đọc kết quả tài liệu mà process tạo ra, kiểm tra giả định trước cho phép triển khai.'],caution:'Một spec viết rõ vẫn có thể chứa giả định sai; không coi template hoặc nhiều tài liệu là bằng chứng dự án đã hoạt động.'},
54:{fact:'Awesome Claude Skills là danh sách tuyển chọn có nhiều nguồn skill/plugin và cả hướng kết nối ứng dụng qua Composio. Cần phân biệt link tham khảo với plugin có thể gửi email, tạo issue hoặc tác động dịch vụ ngoài.',requirements:'Chọn một skill rồi đọc nguồn gốc, yêu cầu công cụ và quyền; plugin kết nối app có bước xác thực và điều kiện riêng.',steps:['Duyệt danh mục theo công việc, chọn một nguồn và mở repo/thư mục tác giả.','Đọc skill trước, tách chỉ dẫn tạo nội dung khỏi chỉ dẫn gọi công cụ ngoài.','Nếu chỉ muốn học cấu trúc, chưa cần kết nối app hoặc gửi một email thử; ghi quyền dự kiến vào checklist.'],caution:'Danh sách tổng hợp không chứng minh từng thành phần đã được website thử hoặc đủ an toàn cho tài khoản của bạn.'},
55:{fact:'Agent Skills của Addy Osmani tổ chức skills theo vòng đời làm phần mềm, với các command như đặc tả, kế hoạch, xây dựng, kiểm tra và review. README nhấn mạnh quy trình kỹ thuật; không phải bộ thao tác dùng chung cho mọi việc văn phòng.',requirements:'Cần hiểu dự án mã nguồn ở mức cơ bản và chọn đường Quick Start đúng agent; đọc command/skill định dùng trước.',steps:['Chọn một nhu cầu như viết tiêu chí trước làm hoặc review thay đổi, thay vì bật mọi command.','Đọc mô tả skill và giới hạn công cụ mà nó sử dụng.','Dùng thư mục mẫu để xem đầu ra, rồi so sánh với yêu cầu ban đầu và cách kiểm chứng bạn đã định.'],caution:'Tên gọi production-grade trong README là mô tả của tác giả, không phải kết quả website tự chứng nhận.'},
56:{fact:'Anthropic Courses tập hợp các bài về API, prompting, evaluation và tool use. Snapshot GitHub ghi repo archived; README còn nêu model cũ và các bài chạy API, vì vậy cần đọc như tư liệu học có mốc lịch sử, không dùng làm bảng tính năng/giá hiện tại.',requirements:'Phần notebook/API cần môi trường lập trình và quyền tài khoản; nội dung giữ tham khảo, phải đối chiếu tài liệu hiện hành trước chạy.',steps:['Đọc danh sách khóa để phân biệt kiến thức khái niệm với bài cần gọi dịch vụ.','Chọn một bài và ghi thuật ngữ/mục tiêu muốn học, chưa chạy toàn notebook.','Đối chiếu tên model, SDK và chi phí bằng nguồn hiện hành trước thử trên môi trường được phép.'],caution:'Không coi model được đề xuất trong khóa archived là model rẻ nhất hoặc phù hợp nhất hiện tại.'},
57:{fact:'Prompt Engineering Interactive Tutorial có chương và bài tập thiết kế prompt theo trình tự, kèm khu vực thử ví dụ. README nêu các model thế hệ cũ; giá trị nên khai thác là cách đặt mục tiêu và tự kiểm tra, không sao chép kết luận model/giá như hiện hành.',requirements:'Cần công cụ/tài khoản phù hợp nếu chạy bài; xem định dạng tutorial, phiên bản model và điều kiện gọi dịch vụ trước.',steps:['Chọn một bài đầu và đọc mục tiêu trước phần ví dụ.','Viết prompt bằng tiếng Việt với đầu vào giả và đầu ra mong đợi có thể đối chiếu.','Ghi phản hồi thực sự quan sát nếu thử trong môi trường được phép; chưa thử thì giữ ở mức bài đọc.'],caution:'Không mô tả đáp án ví dụ là kết quả chắc chắn của mọi phiên AI hoặc chứng nhận người học đã thành thạo.'},
58:{fact:'AI for Beginners của Microsoft là giáo trình nền tảng với bài học, quiz và lab, gồm cả khái niệm và công cụ kỹ thuật. README chia đường cho người mới và thiết lập đầy đủ; đọc giáo trình khác với chọn một app dùng ngay.',requirements:'Đọc Getting Started theo nền tảng đang có; lab có thể cần môi trường và kiến thức lập trình được từng bài nêu.',steps:['Chọn đường New to AI nếu chưa biết thuật ngữ thay vì cài toàn bộ môi trường khóa học.','Đọc một mục tiêu bài, ghi ba khái niệm cần giải thích bằng ví dụ tiếng Việt.','Sau phần đọc, kiểm tra bài có yêu cầu chạy code hay dịch vụ ngoài trước thực hiện lab.'],caution:'Thời lượng/độ dễ được tác giả mô tả không bảo đảm mọi người hoàn thành cùng tốc độ; không chạy toàn khóa chỉ để duyệt bài.'},
59:{fact:'Generative AI for Beginners là khóa học về xây ứng dụng AI tạo sinh, có bài và điều kiện thực hành được README tách riêng. Các lựa chọn dịch vụ/công cụ trong bài cần đọc theo môi trường, không suy từ chữ beginners rằng không cần tài khoản hoặc nền kỹ thuật.',requirements:'Đọc Getting Started và What You Need; phần code có yêu cầu môi trường/provider được từng bài quy định.',steps:['Xác định mục tiêu học là hiểu khái niệm hay tự xây một chức năng nhỏ.','Chọn một bài, đọc yêu cầu và phần kết quả mong đợi trước khi mở code.','Kiểm tra dữ liệu, credential và chi phí; chỉ thử bài nhỏ được phép, đối chiếu kết quả với nguồn.'],caution:'Không dùng nguồn học như danh sách model/API luôn cập nhật hoặc hứa mọi tài nguyên của khóa đều không mất phí.'},
60:{fact:'Archify tạo đầu ra trực quan tương tác từ mô tả cho AI agent, bao gồm sơ đồ repo và nhiều tình huống khác. README phân biệt dự án với các dịch vụ online bên thứ ba; cần xác định công cụ nào thực sự xử lý nội dung của bạn.',requirements:'Đọc Get started và đường tích hợp cho agent đang dùng; nguồn mô tả/code có thể được đưa vào phiên AI theo quyền của công cụ đó.',steps:['Mô tả một hệ thống hư cấu có ba thành phần và đường đi dữ liệu.','Đọc ví dụ và cách tích hợp, kiểm tra quyền cần dùng trước cài skill.','Khi có đầu ra thử trong môi trường được phép, đọc từng nhãn/liên kết và so với mô tả gốc thay vì chỉ đánh giá vẻ đẹp.'],caution:'Sơ đồ đẹp có thể diễn giải sai hệ thống; không gửi codebase riêng hoặc cấu hình thật chỉ để tạo ảnh minh họa.'},
61:{fact:'Excalidraw cung cấp bảng vẽ theo phong cách phác tay; README phân biệt thư viện editor với ứng dụng Excalidraw.com. Có định dạng lưu bản vẽ để chỉnh tiếp và các dạng xuất ảnh; đây là hai mục đích khác nhau.',requirements:'Chọn dùng editor có sẵn hay tích hợp vào ứng dụng; tích hợp bằng package cần môi trường lập trình riêng.',steps:['Phác năm nút cho một ý tưởng hư cấu và nối chúng bằng mũi tên có nhãn.','Đọc Features và Excalidraw.com để biết cách lưu bản có thể sửa và cách xuất ảnh.','Mở lại bản lưu mẫu, kiểm tra nhãn tiếng Việt và cách chia sẻ trước dùng với nội dung nhóm.'],caution:'Ảnh PNG/SVG xuất ra không thay thế bản nguồn chỉnh sửa; cần kiểm tra quyền chia sẻ khi cộng tác.'},
62:{fact:'draw.io Desktop đóng gói trình biên tập sơ đồ thành ứng dụng desktop. README mô tả các kiểu bản Windows khác nhau, trong đó quyền admin và việc đăng ký định dạng file không giống nhau; nên chọn theo máy và quyền thực tế.',requirements:'Chọn bản tải chính thức cho OS/kiến trúc; đọc mục Windows installation nếu dùng máy Windows có giới hạn quyền.',steps:['Vẽ luồng ba bước với một nhánh điều kiện bằng nội dung minh họa.','Đọc Releases và phần lựa chọn bản cài, tránh tự xin quyền admin nếu có phương án phù hợp được tài liệu nêu.','Giữ file nguồn, xuất một ảnh rồi mở lại cả hai để phân biệt tài liệu chỉnh sửa với bản chia sẻ.'],caution:'Trình biên tập sơ đồ không tự xác minh quy trình nghiệp vụ; người viết vẫn phải đối chiếu ý nghĩa từng nhánh.'},
63:{fact:'Mermaid tạo sơ đồ từ mô tả văn bản với cú pháp gần cách làm việc cùng Markdown. README có nhiều loại sơ đồ và Live Editor; bản thân thư viện cần môi trường hỗ trợ để hiển thị, không phải mọi ô nhập Markdown đều hiểu cú pháp đó.',requirements:'Chọn Live Editor hoặc môi trường đã hỗ trợ Mermaid; nhúng thư viện vào web là bước cho người có nền lập trình.',steps:['Chọn một flowchart nhỏ thay vì bắt đầu với sơ đồ nhiều thành phần.','Đọc ví dụ cùng loại trong README, viết nhãn rõ và kiểm tra hướng mũi tên.','Xem cách render/xuất ở môi trường định dùng, đối chiếu sơ đồ với mô tả gốc trước chia sẻ.'],caution:'Sơ đồ do AI viết vẫn có thể sai logic hoặc cú pháp; không coi việc render được là quy trình đã đúng.'},
64:{fact:'Repo tldraw tập trung SDK để xây ứng dụng canvas trong React, với khả năng mở rộng shapes, tools và tương tác. Vì vậy cần phân biệt dùng một bảng vẽ có sẵn với dùng thư viện làm nền cho sản phẩm riêng.',requirements:'Tích hợp SDK cần React/môi trường phát triển phù hợp; đọc License và Trademarks trước nhúng vào sản phẩm.',steps:['Xác định bạn chỉ cần phác ý tưởng hay muốn xây một ứng dụng canvas riêng.','Nếu tìm hiểu SDK, đọc Feature highlights và Examples để chọn một tương tác nhỏ.','Đọc điều kiện license cùng cách lưu/sync dữ liệu trước chọn nền tảng cho sản phẩm.'],caution:'Không lấy việc mã nguồn hiển thị công khai làm kết luận mọi cách nhúng hoặc thương mại hóa đều miễn phí.'},
65:{fact:'Penpot là nền tảng thiết kế sản phẩm có cộng tác và lựa chọn self-host. README nhấn mạnh các chuẩn web và mối liên hệ thiết kế–phát triển; một bản thiết kế vẫn cần được triển khai và kiểm tra mới trở thành website hoạt động.',requirements:'Chọn dùng trong trình duyệt hoặc hướng self-host từ Getting started; tài khoản và hạ tầng cần xem theo cách dùng.',steps:['Phác wireframe một trang giới thiệu gồm tiêu đề, lợi ích và CTA.','Đọc User Guide, thử diễn đạt bố cục và kiểu thành phần trước thêm chi tiết trang trí.','Khi chuyển cho người làm web, ghi cả nội dung và hành vi, không chỉ đưa một ảnh thiết kế.'],caution:'Design tokens hoặc inspect không tự bảo đảm giao diện đã responsive, truy cập được hay có backend.'},
66:{fact:'Upscayl dùng model để tăng kích thước/độ rõ cảm nhận của ảnh. README có cảnh báo cần GPU tương thích Vulkan và nhiều GPU tích hợp không hoạt động; đây là điều kiện nên đọc trước chọn ứng dụng chỉ từ ảnh demo.',requirements:'README yêu cầu GPU tương thích Vulkan; chọn Installation đúng OS và kiểm tra tài liệu trước tải hoặc thử xử lý ảnh.',steps:['Giữ một ảnh minh họa có quyền cùng bản gốc để so sánh.','Đọc cảnh báo GPU và hướng cài theo hệ điều hành, chưa hứa máy nào cũng chạy.','Khi có thử thực tế được phép, so sánh vùng chữ/biên/vật thể và kích thước file, không chỉ nhìn toàn ảnh.'],caution:'Chi tiết AI bổ sung có thể không đúng với vật thể thật; không dùng ảnh nâng cấp làm bằng chứng xác thực.'},
67:{fact:'Krita AI Diffusion là plugin đưa tạo/chỉnh ảnh bằng AI vào workflow của Krita. README mô tả dùng vùng chọn, ảnh tham chiếu và backend; plugin, ứng dụng vẽ và model là các thành phần cần kiểm tra cùng nhau.',requirements:'Cần Krita và đường cài plugin/backend theo Getting Started; cấu hình local hoặc dịch vụ có yêu cầu riêng về phần cứng và model.',steps:['Chọn một hình vẽ hư cấu do bạn có quyền dùng, chỉ xác định một vùng muốn sửa.','Đọc Getting Started và User Guide để biết phần nào xử lý trong Krita, phần nào ở backend.','Đối chiếu yêu cầu model/GPU và cách giữ layer/bản gốc trước thực hiện một thay đổi thử.'],caution:'Không coi kết quả tạo từ ảnh tham chiếu là đương nhiên có quyền sử dụng; kiểm tra nguồn ảnh và điều kiện model.'},
68:{fact:'IOPaint giới thiệu các thao tác inpainting/outpainting và nhiều model cho chỉnh sửa vùng ảnh. Snapshot GitHub đánh dấu repo archived; những ví dụ còn trong README chỉ là tư liệu tham khảo, không phải khuyến nghị cài mới hiện hành.',requirements:'Đọc trạng thái archived trước; nếu nghiên cứu lịch sử công cụ, phân biệt model/CPU/GPU và các hướng cài cũ.',steps:['Xác định mục tiêu là hiểu chỉnh vùng ảnh, không phải chọn một giải pháp mới chỉ từ số sao.','Đọc Features để phân biệt xóa vùng, thay vật thể và mở rộng ảnh.','Giữ ảnh gốc có quyền và ghi tiêu chí so sánh; chưa chạy lệnh hoặc tải model từ hướng dẫn cũ khi chưa đối chiếu.'],caution:'Chỉnh sửa có thể tạo nội dung không có thật; không dùng để làm sai lệch bằng chứng hoặc xóa dấu quyền tác giả.'},
69:{fact:'InvokeAI cung cấp môi trường làm việc với hình ảnh, canvas và workflow, với tài liệu installation và model riêng. README nói đây cũng là nền cho các sản phẩm thương mại; repo và dịch vụ trả phí không phải một khái niệm.',requirements:'Đọc Installation and Updates để kiểm tra phần cứng, phiên bản và cách quản lý model; model tải về có điều kiện sử dụng riêng.',steps:['Viết brief một hình minh họa hư cấu kèm kích thước và tiêu chí rõ.','Đọc Features để chọn workflow nhỏ phù hợp thay vì chỉnh mọi tham số.','Xác định model, quyền ảnh và nơi lưu đầu ra trước cài/tải; giữ bản gốc nếu dùng ảnh đầu vào.'],caution:'Không suy giấy phép phần mềm áp dụng luôn cho mọi model hoặc ảnh đầu vào; kết quả vẫn cần rà nội dung.'},
70:{fact:'ComfyUI biểu diễn quá trình xử lý nội dung bằng graph/node và có các đường local/cloud trong README. Graph giúp thấy các thành phần nhưng người mới vẫn cần hiểu model, input và output của từng node trước nhập workflow.',requirements:'Chọn Get Started/Installing đúng môi trường, kiểm tra tài nguyên và model; custom node có thể bổ sung dependency và mã thực thi.',steps:['Đọc một workflow mẫu nhỏ, tìm đầu vào, bước model và nơi ghi kết quả.','Đối chiếu mỗi thành phần với tài liệu, chưa thêm custom node từ nguồn không rõ.','Trước chạy được phép, kiểm tra quyền tài nguyên, dung lượng tải và cách giữ đầu ra tách khỏi file gốc.'],caution:'Không nhập workflow lạ rồi tự cho phép cài mọi thành phần; hình thức node không thay thế việc đọc tác dụng.'},
71:{fact:'Whisper là model nhận dạng lời nói với mã nguồn cho các tác vụ tiếng nói. README có Setup, lựa chọn model/ngôn ngữ và cách gọi; phần mềm trong repo khác với một dịch vụ phiên âm hosted mà người dùng trả phí theo API.',requirements:'Đọc Setup để đối chiếu Python, PyTorch và phụ thuộc xử lý âm thanh; chọn model theo tài nguyên thực tế, không tự tải nhiều bản.',steps:['Chuẩn bị một đoạn tự ghi ngắn có quyền sử dụng và một bản chép tay để đối chiếu.','Đọc Available models and languages, xem chi phí tài nguyên trước khi chọn model.','Nếu thử trong môi trường được phép, kiểm tra tên riêng, số và dấu tiếng Việt thay vì chỉ xem có văn bản xuất ra.'],caution:'Nhận dạng có thể sai hoặc tạo văn bản không có trong âm thanh; luôn nghe lại phần quan trọng.'},
72:{fact:'faster-whisper triển khai Whisper bằng CTranslate2. README có benchmark theo model, precision, beam size và cấu hình; các con số đó chỉ có ý nghĩa trong điều kiện đo đã nêu, không chứng minh nhanh hơn trên mọi máy.',requirements:'Đọc Requirements cho CPU/GPU và các phiên bản thư viện liên quan; model và precision cần chọn theo tài nguyên.',steps:['Ghi rõ mục tiêu là chép lời hay đo hiệu năng trước xem bảng benchmark.','Đọc cấu hình benchmark và Requirements, không so sánh hai máy/model khác nhau rồi kết luận.','Dùng cùng một đoạn âm thanh mẫu nếu thử được phép, ghi thời gian cùng lỗi phiên âm và bộ nhớ.'],caution:'Tên faster không thay thế phép đo công bằng; tốc độ không chứng minh văn bản chính xác.'},
73:{fact:'whisper.cpp là một triển khai suy luận Whisper bằng C/C++, có nhiều backend/nền tảng trong README. Mục Quick start, Memory usage và các phần tăng tốc cần được đọc theo thiết bị; hỗ trợ nhiều nền tảng không nghĩa cùng một cấu hình cho tất cả.',requirements:'Đọc Quick start và phần nền tảng/backend tương ứng; tự build, model và audio đầu vào có yêu cầu riêng.',steps:['Xác định OS, CPU/GPU và mục tiêu chép một đoạn mẫu trước.','Đọc Memory usage và lựa chọn model để biết cần dung lượng/tài nguyên gì.','Chỉ chọn một đường chạy phù hợp; giữ âm thanh gốc và bản đối chiếu khi thử được phép.'],caution:'Không tự cấp micro hoặc tải nhiều model để xem thử; quyền ghi âm và nội dung phải được người tham gia cho phép.'},
74:{fact:'Subtitle Edit cung cấp công cụ biên tập phụ đề và tài liệu/FAQ riêng. README hiện nêu yêu cầu Windows, macOS và Linux theo bản dựng; hướng dẫn cài cũ có thể khác, nhất là runtime và cách đóng gói.',requirements:'Đọc System Requirements đúng OS và bản phát hành; các chức năng AI/dịch nếu dùng cần xem cấu hình dịch vụ riêng.',steps:['Dùng một đoạn video tự tạo có ba câu và bản chép đúng.','Đọc Documentation & FAQ để phân biệt sửa nội dung phụ đề với chỉnh thời gian hiển thị.','Giữ file phụ đề nguồn rồi xem thử cùng video, kiểm tra dấu tiếng Việt và mốc vào/ra.'],caution:'Tự động phiên âm hoặc dịch không thay phần đọc soát; không đưa video riêng lên dịch vụ ngoài khi chưa xác định đường dữ liệu.'},
75:{fact:'Audacity là trình biên tập/ghi âm nhiều track. README hiện cảnh báo repository đang chuyển cấu trúc lớn cho Audacity 4 và phân biệt nhánh phát triển với 3.x; người dùng cuối nên đi theo bản cài chính thức thay vì tự build nhánh master.',requirements:'Chọn bản ứng dụng phù hợp thiết bị từ website chính thức; build từ nguồn có yêu cầu khác và không cần cho bài dùng cơ bản.',steps:['Giữ đoạn ghi âm gốc, tạo bản làm việc riêng trước sửa.','Đọc mô tả phiên bản, chọn một thao tác nhỏ như cắt vùng im lặng.','Khi thử được phép, nghe lại bản xuất từ đầu đến cuối và giữ dự án có thể chỉnh tiếp.'],caution:'Không ghi đè file gốc hoặc đánh giá âm thanh chỉ qua waveform; plugin/hiệu ứng có điều kiện riêng.'},
76:{fact:'Shotcut là trình dựng video desktop nhiều nền tảng. README hướng người dùng tới bản binary và nói tự build dành cho người thử beta/người đóng góp có kinh nghiệm; người mới không cần cài chuỗi dependency của mã nguồn.',requirements:'Chọn bản cài ở trang Download chính thức và xem hệ điều hành/cấu hình phù hợp; không dùng How to build như hướng người dùng cuối.',steps:['Chuẩn bị hai clip hư cấu có quyền và đặt mục tiêu ghép thành đoạn ngắn.','Đọc đường Features/Download trong README, chọn một thao tác timeline cơ bản.','Giữ file dự án và thư mục media, kiểm tra cả hình lẫn âm thanh sau xuất thử.'],caution:'Video xuất có thể khác preview về codec/kích thước; cần mở bản xuất bằng trình phát độc lập để đối chiếu.'},
77:{fact:'OpenShot là trình dựng video hỗ trợ timeline, track và nhiều thao tác hình/âm thanh được README mô tả. Có đường Getting Started, Tutorial và Developers riêng; người chỉ dựng một clip nhỏ không cần tự phát triển thư viện.',requirements:'Đọc Getting Started/Tutorial đúng nền tảng, kiểm tra định dạng đầu vào và điều kiện máy trước chọn bản cài.',steps:['Bắt đầu với hai ảnh có quyền và một tiêu đề tiếng Việt, chưa dùng nhiều hiệu ứng.','Tách mục tiêu bố cục timeline khỏi mục tiêu xuất video để kiểm tra từng bước.','Giữ tài nguyên gốc và dự án, xem bản xuất trọn đoạn trước chia sẻ.'],caution:'Không suy hỗ trợ nhiều định dạng là mọi file đều mở/chạy mượt trên máy; thử mẫu nhỏ trước dự án dài.'},
78:{fact:'yt-dlp là công cụ dòng lệnh tải nội dung âm thanh/video với nhiều tùy chọn và định dạng. README tách release files, dependency và các nhóm tùy chọn; việc công cụ hỗ trợ một website không tự cấp quyền tải hoặc vượt kiểm soát truy cập của website đó.',requirements:'Chọn bản phát hành phù hợp và đọc Dependencies cho tác vụ cần dùng; chỉ dùng nguồn bạn có quyền và điều kiện dịch vụ cho phép.',steps:['Xác định quyền với một video do chính bạn sở hữu trước khi xem cách dùng.','Đọc Installation và nhóm tùy chọn metadata/simulation để hiểu thông tin mà chưa cần tải nội dung.','Khi có nhu cầu hợp lệ, xác định tên file, thư mục đích và dung lượng; chưa dùng cookie/tài khoản người khác.'],caution:'Không hướng dẫn vượt paywall, DRM hoặc giới hạn truy cập; chức năng tải không thay thế quyền nội dung.'},
79:{fact:'Blender là bộ công cụ 3D bao gồm nhiều giai đoạn từ dựng hình tới render và compositing. README dẫn Reference Manual và trang phát triển riêng; người mới nên dùng tài liệu người dùng, không bắt đầu bằng build instructions.',requirements:'Chọn bản ứng dụng chính thức và xem yêu cầu phần cứng từ tài liệu; build mã nguồn không cần cho việc làm quen giao diện.',steps:['Đặt mục tiêu một cảnh hư cấu thật nhỏ với đối tượng, camera và đầu ra.','Mở Reference Manual từ Project Pages, học thao tác cơ bản trước yêu cầu AI viết script.','Giữ file dự án rồi đối chiếu khung hình/ánh sáng với mục tiêu khi thử trên máy phù hợp.'],caution:'Không coi prompt có thể thay toàn bộ kiến thức về cảnh 3D; render và lưu dự án là các phần cần kiểm tra riêng.'},
80:{fact:'Manim Community là engine tạo hoạt hình giải thích bằng mã. README phân biệt bản community với repo gốc của Grant Sanderson và cảnh báo trộn hướng cài giữa các bản sẽ gây vấn đề; chọn đúng phiên bản trước xem ví dụ.',requirements:'Cần môi trường Python và dependency theo Installation của Manim Community; không dùng lệnh cài của repo Manim khác.',steps:['Xác nhận đang đọc Manim Community trước khi mở Installation hoặc Usage.','Chọn hoạt hình một hình/nhãn đơn giản với kết quả có thể mô tả bằng lời.','Đọc cách render và lưu đầu ra, kiểm tra dấu tiếng Việt/phông khi thử trong môi trường được phép.'],caution:'Video ví dụ không chứng minh code trên máy đã chạy; cần giữ source và đối chiếu bản render thật.'},
81:{fact:'DuckDB là hệ quản trị phân tích chạy trong tiến trình ứng dụng, có CLI và client cho nhiều ngôn ngữ. README nêu khả năng đọc file và kết nối nguồn khác; cách dùng tối thiểu không cần dựng server riêng nhưng truy cập nguồn ngoài vẫn có quyền riêng.',requirements:'Chọn client/CLI đúng môi trường trong Installation; cần hiểu SQL tối thiểu và định dạng dữ liệu định đọc.',steps:['Dùng CSV mười dòng với cột và kiểu dữ liệu rõ, đặt một câu hỏi có thể tính tay.','Đọc đường CLI hoặc client phù hợp, chưa thêm extension/kết nối ngoài không cần thiết.','Khi thử được phép, đối chiếu số dòng, giá trị thiếu và kết quả nhóm với bảng gốc.'],caution:'Truy vấn không báo lỗi không chứng minh kiểu dữ liệu, điều kiện lọc hoặc kết quả phân tích đã đúng.'},
82:{fact:'Metabase giúp đặt câu hỏi và làm dashboard từ dữ liệu; README tách dịch vụ Cloud với self-host và có cả cách dùng không viết SQL lẫn SQL editor. Để chọn đúng, cần hiểu nguồn dữ liệu và câu hỏi hơn là chỉ xem ảnh dashboard.',requirements:'Chọn Get started cloud hoặc Installation self-host, đối chiếu database được hỗ trợ và quyền đọc nguồn.',steps:['Viết định nghĩa ba chỉ số trên bảng doanh số hư cấu, kèm kỳ đo và đơn vị.','Đọc Supported databases và Documentation để chọn cách kết nối phù hợp.','Xác định ai được xem dữ liệu/giao diện trước chia sẻ, chưa dùng database production trong bài đầu.'],caution:'Không lặp lời hứa thiết lập vài phút như cam kết cho mọi hệ thống; quyền và chất lượng dữ liệu có thể cần nhiều bước hơn.'},
83:{fact:'Apache Superset là ứng dụng business intelligence có tài liệu riêng cho người phân tích, quản trị và lập trình viên. Tách đúng vai trò giúp người mới tránh bắt đầu bằng phần vận hành server khi mục tiêu chỉ là hiểu biểu đồ/dashboard.',requirements:'Người dùng chọn User Guide; người tự host cần Administrator Guide, database driver và cấu hình theo môi trường.',steps:['Phác một dashboard mẫu với ba câu hỏi và bảng dữ liệu giả.','Mở User Guide để đọc cách tạo chart/dashboard, tách khỏi hướng cài của quản trị viên.','Trước triển khai, yêu cầu người vận hành xác định kết nối, quyền và giới hạn truy vấn.'],caution:'Dashboard đẹp không thay việc định nghĩa chỉ số hoặc kiểm tra quyền; chưa dùng như công cụ đầu tiên nếu không có môi trường phù hợp.'},
84:{fact:'PostHog tập hợp các công cụ phân tích sản phẩm, sự kiện và nhiều loại dữ liệu được README mô tả. Các chức năng analytics/session replay liên quan dữ liệu người dùng; bài giới thiệu chỉ nên bắt đầu bằng sơ đồ sự kiện giả, chưa bật theo dõi website thật.',requirements:'Đọc Getting started theo Cloud hoặc self-host nâng cao; phải xác định dữ liệu thu thập và cách cấu hình quyền riêng tư trước tích hợp.',steps:['Chọn một câu hỏi như người đọc có tìm được bài, rồi mô tả sự kiện bằng dữ liệu hư cấu.','Đọc phạm vi từng chức năng để phân biệt thống kê tổng hợp với ghi lại phiên.','Lập danh sách trường cần/không cần thu trước cân nhắc SDK hoặc dashboard.'],caution:'Không cài tracking chỉ để kiểm tra bài; không coi một sản phẩm hỗ trợ analytics là mặc nhiên phù hợp mọi chính sách dữ liệu.'},
85:{fact:'Apache ECharts là thư viện JavaScript để làm biểu đồ tương tác cho sản phẩm web. README dẫn Get Started, API, Option Manual và Examples; ví dụ biểu đồ là điểm học, không phải ứng dụng hoàn chỉnh tự thay công cụ bảng tính.',requirements:'Cần môi trường web/JavaScript hoặc công cụ tích hợp đã hỗ trợ; chọn một cách dùng trong Get Apache ECharts.',steps:['Chuẩn bị ba nhóm và ba giá trị giả có đơn vị rõ, chọn biểu đồ cột.','Đọc ví dụ cùng loại và ý nghĩa trục/nhãn trước tùy biến màu.','Nếu thử được phép, kiểm tra nhãn tiếng Việt, dữ liệu rỗng và kích thước hiển thị.'],caution:'Khả năng tương tác không ngăn biểu đồ gây hiểu nhầm; trục, đơn vị và nguồn dữ liệu vẫn cần được giải thích.'},
86:{fact:'Grafana cho phép truy vấn, trực quan hóa và cảnh báo trên các nguồn chỉ số/log. README nêu dashboard, explore và alerting; cần phân biệt giao diện theo dõi với hệ thống tạo/lưu dữ liệu phía sau.',requirements:'Chọn Get started và datasource phù hợp; cần endpoint dữ liệu có quyền truy cập, cấu hình người dùng và phạm vi cảnh báo.',steps:['Vẽ sơ đồ nguồn đo → chỉ số → dashboard bằng tên giả.','Chọn một chỉ số, ghi đơn vị, khoảng thời gian và điều kiện bất thường.','Đọc datasource và quyền chia sẻ trước thêm alert hay gửi thông báo tới kênh thật.'],caution:'Một dashboard không có dữ liệu hoặc trả 200 không chứng minh hệ thống khỏe; cảnh báo phải được kiểm tra theo ngữ nghĩa chỉ số.'},
87:{fact:'Plotly.py là thư viện Python tạo biểu đồ tương tác, có đường Graph Objects và Plotly Express trong README. Việc xem trong notebook, xuất ảnh và chia sẻ HTML có yêu cầu khác; nên chọn đầu ra cần dùng trước cài thêm thành phần.',requirements:'Cần Python; Plotly Express còn cần thư viện dataframe được hỗ trợ, còn xuất ảnh tĩnh có tài liệu riêng.',steps:['Chọn bảng nhỏ và biểu đồ đơn giản với mục tiêu giải thích rõ bằng tiếng Việt.','Đọc Quickstart cho Graph Objects hoặc Express, không trộn hai lối khi chưa hiểu.','Xác định đầu ra cần là notebook, HTML hay ảnh, rồi xem hướng Installation tương ứng trước thử.'],caution:'File HTML chia sẻ có thể chứa dữ liệu biểu đồ; cần xem dữ liệu đi kèm, không chỉ nội dung nhìn thấy trên ảnh.'},
88:{fact:'Streamlit biến script Python thành ứng dụng web tương tác và có nền tảng cloud để triển khai. README tách phần cài/chạy app khỏi chia sẻ; dựng giao diện trên máy chưa đồng nghĩa người khác có thể dùng an toàn qua mạng.',requirements:'Cần Python và môi trường dự án; dùng Community Cloud có điều kiện tài khoản/triển khai riêng.',steps:['Chọn một bảng hư cấu và một bộ lọc có kết quả mong đợi rõ ràng.','Đọc What is Streamlit và Quickstart để hiểu script được trình bày thành app thế nào.','Giữ dữ liệu/secret tách khỏi mã, kiểm tra phạm vi truy cập trước cân nhắc chia sẻ app.'],caution:'Không commit key vào repo hoặc triển khai dataset riêng như một ví dụ; giao diện chạy được không thay kiểm tra dữ liệu.'},
89:{fact:'Gradio tạo giao diện cho model, API hoặc hàm Python và có tính năng chia sẻ demo. README nêu phiên bản Python tối thiểu và các đường building/sharing; việc làm demo local khác với mở một link cho người khác truy cập.',requirements:'README yêu cầu Python 3.10 trở lên, khuyến nghị môi trường ảo; model/API phía sau có điều kiện riêng.',steps:['Chọn hàm xử lý chuỗi giả với đầu vào/đầu ra có thể kiểm tra bằng mắt.','Đọc Building Your First Demo để xác định component và hàm cần gọi.','Trước Sharing Your Demo, xác định ai có thể truy cập và dữ liệu nào có thể bị gửi vào/hiển thị.'],caution:'Không mở link chia sẻ cho hàm có quyền đọc file riêng hoặc gọi dịch vụ trả phí khi chưa có kiểm soát.'},
90:{fact:'Reflex là thư viện xây ứng dụng web bằng Python cho cả phần giao diện và xử lý. README cũng nêu AI Builder, agent toolkit và hosting như các đường sản phẩm; thư viện, công cụ AI và dịch vụ triển khai có điều kiện riêng.',requirements:'Cần môi trường Python, khuyến nghị virtual environment; đọc Installation và Create your first app trước chọn cách vận hành.',steps:['Phác trang danh sách giả và một thao tác lọc, ghi trạng thái trước/sau.','Đọc Introduction và Example App để hiểu cấu trúc mã, chưa dùng AI Builder như yêu cầu bắt buộc.','Kiểm tra cách lưu dữ liệu và cấu hình môi trường trước cân nhắc deploy hoặc tích hợp agent.'],caution:'Dùng một ngôn ngữ cho frontend/backend không làm mất yêu cầu kiểm tra xác thực, dữ liệu và lỗi.'},
91:{fact:'LocalSend chia sẻ file và tin nhắn giữa thiết bị gần nhau qua mạng cục bộ. README có phần Download, Setup và How It Works; người mới cần phân biệt mạng local và dịch vụ gửi file qua server trên internet.',requirements:'Cần các thiết bị được phép và mạng phù hợp, chọn bản ứng dụng chính thức cho từng thiết bị; đọc Setup nếu không tìm thấy nhau.',steps:['Chuẩn bị file văn bản hư cấu, đặt tên để người nhận dễ nhận biết.','Đọc Download/Setup và xác nhận đúng hai thiết bị, chưa thay cấu hình mạng diện rộng chỉ để thử.','Nếu thử được phép, kiểm tra file đến đúng nơi và mở được rồi mới cân nhắc nội dung khác.'],caution:'Thiết bị có tên quen không tự chứng minh đúng người nhận; không gửi tài liệu riêng khi chưa xác nhận phía nhận.'},
92:{fact:'Syncthing đồng bộ file liên tục giữa hai hoặc nhiều máy. README mô tả mục tiêu và đường Getting Started; cần hiểu đây là đồng bộ trạng thái, không phải tự có một lịch sử backup độc lập cho mọi tình huống.',requirements:'Cần thiết bị/thư mục được phép chia sẻ và cấu hình theo Getting Started; đọc tài liệu về thay đổi/xóa và versioning nếu dùng.',steps:['Vẽ hai thư mục mẫu A/B, ghi thay đổi nào bạn muốn được truyền sang.','Đọc Getting Started và Documentation, hiểu cơ chế nhận thiết bị/chọn thư mục trước kết nối.','Chỉ dùng dữ liệu giả khi thử, kiểm tra cả sửa/xóa và bản sao độc lập trước dùng file thật.'],caution:'Sai sót trên một bên có thể lan sang bên đồng bộ; đừng đặt kho ghi chú duy nhất vào thử nghiệm đầu tiên.'},
93:{fact:'rclone là công cụ dòng lệnh làm việc với file/thư mục ở nhiều nhà cung cấp lưu trữ. README liệt kê backend và chức năng; quyền, quota và tác dụng của thao tác copy/sync/move không giống nhau nên phải đọc đúng tác vụ.',requirements:'Cần bản rclone cho môi trường phù hợp và quyền backend nếu kết nối dịch vụ; xem documentation trước cấu hình credential.',steps:['Ghi rõ nguồn, đích và mục đích của một thao tác trên thư mục giả.','Đọc tài liệu đúng backend và phân biệt sao chép với đồng bộ trước xem ví dụ lệnh.','Chưa nhập credential hoặc dùng đường dẫn thật cho tới khi có phương án kiểm tra/khôi phục.'],caution:'Không biến ví dụ sync thành lệnh dùng ngay với dữ liệu quan trọng; thay đổi và xóa có thể ảnh hưởng nơi đích.'},
94:{fact:'restic tạo kho backup và snapshot có cơ chế truy cập bằng mật khẩu được README mô tả. Quick start nhấn mạnh mất mật khẩu có thể không khôi phục được; nhiệm vụ sao lưu phải bao gồm cách giữ quyền truy cập và thử phục hồi.',requirements:'Chọn bản cài và backend phù hợp, xác định nơi giữ mật khẩu/khóa cùng dung lượng lưu; chỉ dùng dữ liệu giả trong bước làm quen.',steps:['Dùng hai file hư cấu và mô tả trạng thái cần khôi phục trước khi tạo kế hoạch backup.','Đọc Quick start/Backends để hiểu kho, snapshot và thông tin truy cập.','Khi thử được phép, phục hồi ra thư mục khác rồi so nội dung; không chỉ nhìn thông báo backup xong.'],caution:'Không dùng mật khẩu ví dụ cho kho thật và không mất khóa; bản backup không đọc lại được không giải quyết nhu cầu phục hồi.'},
95:{fact:'Nextcloud Server là nền tảng lưu, đồng bộ và chia sẻ dữ liệu trên máy chủ được lựa chọn, có hệ sinh thái ứng dụng. README tách dùng Nextcloud với phát triển mã nguồn; tự vận hành cần công chăm sóc hạ tầng và quyền tài khoản.',requirements:'Chọn đường Get your Nextcloud phù hợp; nếu self-host cần server, cấu hình và cập nhật theo tài liệu người quản trị.',steps:['Vẽ sơ đồ máy chủ, người dùng và thư mục chia sẻ bằng dữ liệu minh họa.','Đọc tính năng cần dùng, chưa cài nhiều app mở rộng cùng lúc.','Lập quyền xem/sửa và kế hoạch sao lưu trước nhập file thật hoặc mời người khác.'],caution:'Tự host không tự bảo đảm riêng tư/an toàn; link chia sẻ, tài khoản và cập nhật vẫn cần quản lý.'},
96:{fact:'Immich quản lý ảnh/video tự triển khai và README đặt cảnh báo sao lưu nổi bật ở đầu. Các mục Installation, Demo và Features giúp khảo sát sản phẩm, nhưng demo công khai không phải nơi đưa ảnh cá nhân lên thử.',requirements:'Đọc Installation requirements theo môi trường server và thiết bị; cần kế hoạch backup độc lập trước nhập kho ảnh thật.',steps:['Chọn vài ảnh minh họa có quyền và mô tả cách bạn muốn tổ chức album.','Đọc cảnh báo backup, yêu cầu cài và tính năng hỗ trợ cho web/mobile.','Nếu dùng môi trường thử được phép, kiểm tra file gốc, metadata và khả năng phục hồi trước nhập số lượng lớn.'],caution:'Không coi ứng dụng quản lý ảnh là bản sao lưu duy nhất; không tải ảnh gia đình lên demo của người khác.'},
97:{fact:'PhotoPrism hỗ trợ duyệt, tổ chức và chia sẻ ảnh/video với khả năng tìm kiếm gắn AI được README mô tả. Có đường self-host/cloud và demo công khai; tài liệu còn nhắc không upload ảnh riêng vào demo.',requirements:'Đọc Getting Started và yêu cầu triển khai, nơi lưu originals/database và điều kiện tính năng của cách dùng định chọn.',steps:['Dùng album sản phẩm hư cấu có metadata tối thiểu để xác định nhu cầu tìm kiếm.','Đọc Feature Overview và Getting Started, phân biệt ảnh gốc với dữ liệu chỉ mục.','Kiểm tra backup và quyền chia sẻ trước nhập thật; nếu khảo sát demo chỉ xem dữ liệu đã có.'],caution:'Nhận dạng/gắn nhãn có thể sai; không lấy nhãn AI làm bằng chứng xác định người hoặc sự kiện.'},
98:{fact:'Memos là ứng dụng ghi chú tự host theo timeline, có tags và chế độ giữ riêng/chia sẻ được README mô tả. Khả năng xuất bản ghi chú lên web là lựa chọn của người dùng, không nên mặc định mọi memo đều riêng hoặc đều công khai.',requirements:'Chọn Quick start, cần môi trường server nếu tự host; đọc quyền chia sẻ và cách nâng cấp/sao lưu trước dùng dài hạn.',steps:['Viết mười ghi chú mẫu cho một tuần học, gắn vài tag để tìm lại.','Đọc About Memos để phân biệt timeline, tag và shared spaces.','Trước dùng nội dung thật, kiểm tra chế độ xem/chia sẻ từng loại ghi chú và bản sao dữ liệu.'],caution:'Một ghi chú ngắn vẫn có thể chứa thông tin nhạy cảm; đừng công khai chỉ vì định dạng trông như dòng trạng thái.'},
99:{fact:'Planka tổ chức công việc bằng board, list và card, với bảng phân biệt Community/Pro trong README. Một số kiểu hiển thị và tính năng cộng tác thuộc điều kiện khác; người mới nên chọn nhu cầu tối thiểu trước so sánh gói.',requirements:'Chọn bản Community/Pro và hướng Deploy phù hợp; self-host cần database/backup, cloud có điều kiện tài khoản riêng.',steps:['Phác ba cột cần làm, đang làm và xong cho dự án hư cấu.','Đọc bảng edition để biết các chức năng mong muốn có thuộc bản đang chọn.','Định nghĩa tiêu chí xong trên mỗi card, kiểm tra quyền thành viên và thông báo trước dùng cho nhóm thật.'],caution:'Không bật webhook hoặc thông báo gửi ra dịch vụ ngoài chỉ để làm bảng mẫu; quyền và dữ liệu đính kèm cần quản lý.'},
100:{fact:'Uptime Kuma theo dõi nhiều dạng endpoint và có thông báo/status page theo README. Uptime là một tín hiệu vận hành, khác với kiểm tra nội dung bài hoặc toàn bộ chức năng website; cần chọn loại kiểm tra phù hợp câu hỏi.',requirements:'Chọn How to Install và cấu hình lưu dữ liệu/mạng; chỉ theo dõi URL được phép, thông báo cần tài khoản/kênh riêng.',steps:['Viết rõ bạn muốn biết server có phản hồi hay một từ khóa/nội dung có xuất hiện.','Đọc Features và chọn một loại monitor, chưa bật nhiều kênh thông báo cùng lúc.','Nếu thử được phép, dùng endpoint kiểm thử và đối chiếu tình huống khỏe/lỗi; giữ quyền status page rõ ràng.'],caution:'HTTP 200 có thể vẫn là trang sai nội dung; không lấy trạng thái xanh làm bằng chứng mọi tính năng đều đúng.'},
};
